import React, { useEffect, useState } from 'react';
import { createCar, getCars, deleteCar } from '../services/carService';
import { getAllTestDrives } from '../services/testDriveService';
import { motion } from 'framer-motion';

const AdminPanel = () => {
  const [cars, setCars] = useState([]);
  const [testDrives, setTestDrives] = useState([]);
  const [newCar, setNewCar] = useState({ brand: '', model: '', year: '', price: '', description: '', image_url: '' });

  const fetchData = async () => {
    const carsRes = await getCars();
    const tdRes = await getAllTestDrives();
    setCars(carsRes.data);
    setTestDrives(tdRes.data);
  };

  useEffect(() => { fetchData(); }, []);

  const handleAddCar = async (e) => {
    e.preventDefault();
    const carData = { ...newCar, year: parseInt(newCar.year), price: parseFloat(newCar.price) };
    try {
      await createCar(carData);
      fetchData();
      setNewCar({ brand: '', model: '', year: '', price: '', description: '', image_url: '' });
    } catch (err) { alert('Ошибка добавления'); }
  };

  const handleDelete = async (id) => {
    await deleteCar(id);
    fetchData();
  };

  return (
    <div style={{ padding: '2rem' }}>
      <h2>Админ-панель</h2>
      <h3>Добавить автомобиль</h3>
      <form onSubmit={handleAddCar} style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap', marginBottom: '2rem' }}>
        <input placeholder="Марка" value={newCar.brand} onChange={e => setNewCar({...newCar, brand: e.target.value})} required />
        <input placeholder="Модель" value={newCar.model} onChange={e => setNewCar({...newCar, model: e.target.value})} required />
        <input placeholder="Год" type="number" value={newCar.year} onChange={e => setNewCar({...newCar, year: e.target.value})} required />
        <input placeholder="Цена" type="number" value={newCar.price} onChange={e => setNewCar({...newCar, price: e.target.value})} required />
        <input placeholder="Описание" value={newCar.description} onChange={e => setNewCar({...newCar, description: e.target.value})} />
        <input placeholder="URL изображения" value={newCar.image_url} onChange={e => setNewCar({...newCar, image_url: e.target.value})} />
        <button type="submit">Добавить</button>
      </form>

      <h3>Список автомобилей</h3>
      <ul>
        {cars.map(car => (
          <li key={car.id}>{car.brand} {car.model} – <button onClick={() => handleDelete(car.id)}>Удалить</button></li>
        ))}
      </ul>

      <h3>Заявки на тест-драйв</h3>
      <ul>
        {testDrives.map(td => (
          <li key={td.id}>ID:{td.id}, авто {td.car_id}, пользователь {td.user_id}, дата {td.preferred_date}</li>
        ))}
      </ul>
    </div>
  );
};

export default AdminPanel;
